import calc


def test_add():
    assert calc.add(2, 3) == 5
    assert calc.add(-1, 1) == 0


def test_divide_returns_float():
    assert calc.divide(7, 2) == 3.5
    assert isinstance(calc.divide(4, 2), float)


def test_divide_by_zero_returns_none():
    assert calc.divide(1, 0) is None


def test_mean_of_empty_is_zero():
    assert calc.mean([]) == 0


def test_mean_rounds_to_two_places():
    assert calc.mean([1, 2, 2]) == 1.67


def test_apply_uses_operation_names():
    assert calc.apply('add', 2, 3) == 5
    assert calc.apply('divide', 9, 3) == 3.0


def test_apply_unknown_operation_raises_keyerror():
    try:
        calc.apply('modulo', 1, 2)
    except KeyError:
        return
    raise AssertionError('expected KeyError')

